import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import type { UserDetail } from '@/types/user'
import * as authApi from '@/api/auth'
import { getToken, setToken, clearToken, getUser, setUser } from '@/utils/auth'
import { removeEssayTemp } from '@/utils/essayTempCache'

export const useAuthStore = defineStore('auth', () => {
  const token = ref<string | null>(getToken())
  const user = ref<UserDetail | null>(getUser() as UserDetail | null)

  const isAuthenticated = computed(() => !!token.value && !!user.value)
  const isAdmin = computed(() => user.value?.role === 'admin')
  // 时间型会员：有有效到期日且未过期算会员（与是否还有 quota_remaining 无关）
  const isMember = computed(() => {
    const m = user.value?.membership
    if (!m) return false
    const exp = m.expired_at && String(m.expired_at).trim()
    if (!exp || exp.startsWith('0001')) return false // 仅次数卡无时间到期
    return new Date(m.expired_at) > new Date() && m.status === 'active'
  })

  async function login(emailOrPhone: string, password: string) {
    const response = await authApi.login({ emailOrPhone, password })
    token.value = response.access_token
    setToken(response.access_token, response.refresh_token)

    const userInfo = await authApi.getCurrentUser()
    user.value = userInfo
    setUser(userInfo)
  }

  async function register(data: {
    email: string
    email_code: string
    phone?: string
    password: string
    nickname: string
  }) {
    await authApi.register(data)
  }

  async function fetchUser() {
    try {
      const userInfo = await authApi.getCurrentUser()
      user.value = userInfo
      setUser(userInfo)
    } catch {
      logout()
    }
  }

  async function logout() {
    await authApi.logout()
    token.value = null
    user.value = null
    clearToken()
    removeEssayTemp()
  }

  function clearLocal() {
    token.value = null
    user.value = null
    clearToken()
    removeEssayTemp()
  }

  return {
    token,
    user,
    isAuthenticated,
    isAdmin,
    isMember,
    login,
    register,
    fetchUser,
    logout,
    clearLocal,
  }
})
