import request from '@/utils/request'
import type {
  LoginRequest,
  LoginResponse,
  RegisterRequest,
  RegisterResponse,
  UserDetail,
} from '@/types/user'

// 登录
export async function login(data: LoginRequest): Promise<LoginResponse> {
  const res = await request.post<LoginResponse>('/auth/login', data)
  return res.data
}

// 发送邮箱验证码（注册/忘记密码用）
export async function sendEmailCode(email: string): Promise<void> {
  await request.post('/auth/send-email-code', { email })
}

// 忘记密码：邮箱+验证码重置
export async function resetPassword(data: {
  email: string
  email_code: string
  new_password: string
}): Promise<void> {
  await request.post('/auth/reset-password', data)
}

// 注册
export async function register(data: RegisterRequest): Promise<RegisterResponse> {
  const res = await request.post<{ user_id: number }>('/auth/register', data)
  return { user_id: res.data.user_id }
}

// 获取当前用户信息（GET /users/me）
export async function getCurrentUser(): Promise<UserDetail> {
  const res = await request.get<Record<string, unknown>>('/users/me')
  const d = res.data
  const membership = d.membership as
    | { plan: string; expired_at: string; status: string; quota_remaining?: number | null }
    | undefined
  return {
    id: d.id as number,
    email: d.email as string,
    phone: d.phone as string | undefined,
    nickname: (d.nickname as string) || '',
    avatar: d.avatar as string | undefined,
    role: d.role as UserDetail['role'],
    status: d.status as UserDetail['status'],
    ink_drops: (d.ink_drops as number) ?? 0,
    created_at: (d.created_at as string) ?? '',
    updated_at: (d.updated_at as string) ?? '',
    checkin_week_count: (d.checkin_week_count as number) ?? 0,
    checkin_today_done: (d.checkin_today_done as boolean) ?? false,
    ...(membership && {
      membership: {
        id: 0,
        user_id: d.id as number,
        plan: membership.plan as 'student' | 'teacher',
        started_at: '',
        expired_at: membership.expired_at,
        status: membership.status as 'active' | 'expired' | 'cancelled',
        quota_remaining: membership.quota_remaining ?? undefined,
        created_at: '',
        updated_at: '',
      },
    }),
  }
}

// 退出登录
export async function logout(): Promise<void> {
  await request.post('/auth/logout', {})
}
