import axios from 'axios'
import type { AxiosInstance, AxiosResponse, InternalAxiosRequestConfig } from 'axios'

/** 扩展请求配置：部分接口需跳过全局错误 toast */
declare module 'axios' {
  interface AxiosRequestConfig {
    skipGlobalErrorToast?: boolean
  }
}
import type { ApiResponse } from '@/types/api'
import { getToken, clearToken } from './auth'
import { removeEssayTemp } from '@/utils/essayTempCache'
import { ElMessage } from 'element-plus'

// 创建axios实例
const service: AxiosInstance = axios.create({
  baseURL: import.meta.env.VITE_API_BASE_URL || '/api/v1',
  timeout: 30000,
  headers: {
    'Content-Type': 'application/json',
  },
})

// 请求拦截器
service.interceptors.request.use(
  (config: InternalAxiosRequestConfig) => {
    const token = getToken()
    if (token && config.headers) {
      config.headers.Authorization = `Bearer ${token}`
    }
    // 上传 FormData 时不要带 Content-Type，让浏览器自动带 boundary
    if (config.data instanceof FormData && config.headers) {
      delete config.headers['Content-Type']
    }
    return config
  },
  (error) => {
    return Promise.reject(error)
  }
)

const base = (import.meta.env.BASE_URL || '/').replace(/\/$/, '') || ''

// 仅在非登录/注册页时跳转登录，避免登录页错误时整页刷新
function shouldRedirectToLogin(): boolean {
  const path = window.location.pathname
  return !path.endsWith('/login') && !path.endsWith('/register')
}

// 带 redirect 的登录页 URL（支持子路径部署如 /ink-ruler-public/）
function loginUrlWithRedirect(): string {
  const full = window.location.pathname + window.location.search
  const loginPath = base ? `${base}/login` : '/login'
  return loginPath + '?redirect=' + encodeURIComponent(full || base || '/')
}

// 响应拦截器
service.interceptors.response.use(
  (response: AxiosResponse<ApiResponse<unknown>>) => {
    const res = response.data

    // 如果code不为0，说明有错误
    if (res.code !== 0) {
      // 401 未登录：不在此弹窗，由调用方弹一次；延迟跳转以便用户看到提示
      if (res.code === 401 && shouldRedirectToLogin()) {
        clearToken()
        removeEssayTemp()
        setTimeout(() => {
          window.location.href = loginUrlWithRedirect()
        }, 400)
        return Promise.reject(new Error('请先登录'))
      }
      ElMessage.error(res.message || '请求失败')
      return Promise.reject(new Error(res.message || '请求失败'))
    }

    // 返回修改后的响应，将 data 替换为实际的业务数据
    return { ...response, data: res.data } as AxiosResponse<unknown>
  },
  (error: unknown) => {
    if (axios.isAxiosError(error) && error.response?.status === 401) {
      clearToken()
      removeEssayTemp()
      if (shouldRedirectToLogin()) {
        setTimeout(() => {
          window.location.href = loginUrlWithRedirect()
        }, 400)
        return Promise.reject(new Error('请先登录'))
      }
      // 登录页不跳转，把后端错误信息带给表单显示
      const msg =
        (error.response?.data as { message?: string })?.message || (error as Error).message
      return Promise.reject(new Error(msg))
    }
    const errorMessage =
      axios.isAxiosError(error) && error.response?.data?.message
        ? (error.response.data as { message?: string }).message
        : error instanceof Error
          ? error.message
          : '网络错误'
    // 有后端文案时只 reject 带文案，由调用方弹窗一次，避免再弹「Request failed with status code 400」
    if (axios.isAxiosError(error) && (error.response?.data as { message?: string })?.message) {
      return Promise.reject(new Error(errorMessage))
    }
    const skipToast = axios.isAxiosError(error)
      ? (error.config as { skipGlobalErrorToast?: boolean })?.skipGlobalErrorToast
      : false
    if (!skipToast) ElMessage.error(errorMessage)
    return Promise.reject(error)
  }
)

export default service
